// visit row-level security and integrity — generated by `pnpm gen:migration` (02-architecture §4,
// 04-testing §3); SOP-DEL-03 §5 / E5 AC3 cases added.
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, expect, inject, it } from 'vitest';
import { createTestDatabase, type TestDatabase } from '@ocs/testing';
import {
  action,
  client,
  createDatabase,
  inActorTransaction,
  migrateUp,
  site,
  visit,
  type Database,
  type DbActor,
} from '../index.ts';

const clientA = randomUUID();
const clientB = randomUUID();
const siteA = randomUUID();
const siteB = randomUUID();
const visitA = randomUUID();
const staff: DbActor = { id: randomUUID(), kind: 'staff', clientIds: [] };
const userOfA: DbActor = { id: randomUUID(), kind: 'client', clientIds: [clientA] };
const userOfB: DbActor = { id: randomUUID(), kind: 'client', clientIds: [clientB] };
const partnerOfA: DbActor = { id: randomUUID(), kind: 'partner', clientIds: [clientA] };
const siteOf = (id: string, clientId: string, projectId: string) => ({
  id,
  clientId,
  projectId,
  countryCode: 'ES',
  cityCode: 'MAD',
  cityName: 'Madrid',
  runningNo: 1,
  name: 'Site 001',
  standard: 'L' as const,
});
const visitOf = (
  clientId: string,
  siteId: string,
  summary: string,
  more: Partial<typeof visit.$inferInsert> = {},
) => ({
  id: randomUUID(),
  clientId,
  siteId,
  type: 'technical_inspection' as const,
  visitDate: '2026-11-02',
  attendees: [
    { name: 'Person A', side: 'vv' as const },
    { name: 'Person B', side: 'client' as const },
  ],
  summary,
  decided: [{ text: 'Remaining zones checked next visit', agreedWith: 'Person B' }],
  coverageDone: 6,
  coverageTotal: 6,
  recordedBy: staff.id,
  ...more,
});
const actionOf = (visitId: string, sourceKind: 'visit' | 'manual', clientId = clientA) => ({
  id: randomUUID(),
  clientId,
  siteId: clientId === clientA ? siteA : siteB,
  title: 'Send the fibre spec',
  ownerId: staff.id,
  due: '2026-11-06',
  sourceKind,
  visitId,
  createdBy: staff.id,
});
let testDb: TestDatabase;
let database: Database;

type Tx = Parameters<Parameters<typeof inActorTransaction>[2]>[0];
const asStaff = <T>(work: (tx: Tx) => Promise<T>) => inActorTransaction(database.db, staff, work);
const visibleTo = (actor: DbActor) =>
  inActorTransaction(database.db, actor, async (tx) =>
    (await tx.select().from(visit)).map((r) => r.summary).sort(),
  );

beforeAll(async () => {
  testDb = await createTestDatabase(inject('postgresUrl'));
  database = createDatabase(testDb.url);
  await migrateUp(database.pool);
  await asStaff(async (tx) => {
    await tx.insert(client).values([
      { id: clientA, shortCode: 'CLIENTA', name: 'Client A' },
      { id: clientB, shortCode: 'CLIENTB', name: 'Client B' },
    ]);
    await tx
      .insert(site)
      .values([siteOf(siteA, clientA, 'CLIENTA-ES-MAD-001'), siteOf(siteB, clientB, 'CLIENTB-ES-MAD-001')]);
    await tx
      .insert(visit)
      .values([
        visitOf(clientA, siteA, 'Coverage confirmed', { id: visitA, visibility: 'client', svrNo: 1 }),
        visitOf(clientA, siteA, 'Switch upgrade checked'),
        visitOf(clientB, siteB, 'Survey done', { type: 'site_survey' }),
      ]);
  });
});

afterAll(async () => {
  await database.close();
  await testDb.drop();
});

it('staff see every visit', async () => {
  expect(await visibleTo(staff)).toHaveLength(3);
});

it('a client sees only its own visits marked for clients', async () => {
  expect(await visibleTo(userOfA)).toEqual(['Coverage confirmed']);
  expect(await visibleTo(userOfB)).toEqual([]);
});

it('a partner sees nothing until a partner policy exists', async () => {
  expect(await visibleTo(partnerOfA)).toEqual([]);
});

it('a client cannot write', async () => {
  await expect(
    inActorTransaction(database.db, userOfA, (tx) => tx.insert(visit).values(visitOf(clientA, siteA, 'X'))),
  ).rejects.toThrow();
});

it('a record has attendees, a summary, a known type and a project of its own client (SOP-DEL-03 §5.1)', async () => {
  for (const bad of [
    { attendees: [] },
    { summary: ' ' },
    { type: 'party' as 'site_survey' },
    { siteId: siteB },
  ]) {
    await expect(
      asStaff((tx) => tx.insert(visit).values(visitOf(clientA, siteA, 'Bad', bad))),
    ).rejects.toThrow();
  }
});

it('coverage is X of Y, and what was not covered says why (§4, §5.1)', async () => {
  await expect(
    asStaff((tx) => tx.insert(visit).values(visitOf(clientA, siteA, 'Too much', { coverageDone: 7 }))),
  ).rejects.toThrow();
  await expect(
    asStaff((tx) =>
      tx.insert(visit).values(visitOf(clientA, siteA, 'Gap', { coverageDone: 6, coverageTotal: 20 })),
    ),
  ).rejects.toThrow();
  await asStaff((tx) =>
    tx.insert(visit).values(
      visitOf(clientA, siteA, 'Gap explained', {
        coverageDone: 6,
        coverageTotal: 20,
        coverageGap: 'No access to top floor',
      }),
    ),
  );
});

it('SVR numbers are unique per project (§5.2)', async () => {
  await expect(
    asStaff((tx) => tx.insert(visit).values(visitOf(clientA, siteA, 'Dup SVR', { svrNo: 1 }))),
  ).rejects.toThrow();
});

it("an action from a visit links to it, says so in its source, and stays in the visit's client", async () => {
  await asStaff((tx) => tx.insert(action).values(actionOf(visitA, 'visit')));
  await expect(asStaff((tx) => tx.insert(action).values(actionOf(visitA, 'manual')))).rejects.toThrow();
  await expect(
    asStaff((tx) => tx.insert(action).values(actionOf(visitA, 'visit', clientB))),
  ).rejects.toThrow();
});
